<div class="metric-grid"><article class="metric-card"><span>On hand</span><strong><?= $q($stock['on_hand_milli']) ?></strong><small><?= $e($stock['sell_unit']) ?></small></article><article class="metric-card"><span>Reserved</span><strong><?= $q($stock['reserved_milli']) ?></strong><small><?= $e($stock['sell_unit']) ?></small></article><article class="metric-card"><span>Available</span><strong><?= $q($stock['on_hand_milli']-$stock['reserved_milli']) ?></strong><small><?= $e($stock['sell_unit']) ?></small></article></div>
<section class="panel"><div class="panel-heading"><div><h2>Adjust inventory</h2><p>Record received stock or a correction. Every adjustment is audited.</p></div><span class="pill">Revision <?= $e($stock['revision']) ?></span></div><?php if($can('admin.inventory.adjust')): ?><form method="post" action="<?= $u('admin/stock') ?>" data-validate><?php $hidden(['csrf'=>$csrf,'variant_id'=>$stock['variant_id'],'revision'=>$values['revision']??$stock['revision'],'operation_key'=>$values['operation_key']??$key()]); ?><div class="form-grid"><?php $field('quantity','Quantity change ('.$stock['sell_unit'].')',$values['quantity']??'','number','required step="'.AdminReadService::decimal($stock['qty_increment_milli'],3).'" min="-1000000" max="1000000"');$field('reason','Reason for adjustment',$values['reason']??'','text','required maxlength="190"'); ?></div><p class="help-text">Use a positive quantity for received stock, or a negative quantity for a correction. Increment: <?= $q($stock['qty_increment_milli']) ?> <?= $e($stock['sell_unit']) ?>. Zero changes and reductions below reserved stock are rejected.</p><div class="form-actions"><button class="button">Save adjustment</button><a class="button secondary" href="<?= $u('admin/inventory') ?>">Back to inventory</a></div></form><?php else: ?><p class="notice">Your account can review stock. Stock adjustments require an additional permission.</p><?php endif; ?></section>
